// /app/app/sim-avatar.js — the simulated-roster PFP, rendered in the browser.
//
// The testnet bot identities used to get their avatar from the API
// (`/players/<addr>/avatar.svg`). In chain mode there is no API, but the image
// never needed one: it is a pure function of the seed, the three palette
// colours and the player type, so the same drawing is reproduced here and
// handed out as a data: URI.
//
// Ported from database/src/api/utils/sim-player-profiles.ts
// (renderSimPlayerAvatarSvg / renderVaultAvatarSvg). Keep the two in step —
// they are the same picture, and the API lane still serves the original while
// the testnet database is alive.

const cache = new Map();

function escapeXml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;',
  }[char]));
}

function profileInitials(name) {
  const words = String(name || '').trim().split(/\s+/).filter(Boolean);
  return words.slice(0, 2).map((word) => word[0]?.toUpperCase() ?? '').join('') || 'DG';
}

/** A deliberately bespoke safe-door PFP for the protocol Vault identity. */
function renderVault(colors, name, type) {
  const [background, gold, bronze] = colors;
  const title = escapeXml(`${name} — ${type}`);
  return [
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img">',
    `<title>${title}</title>`,
    '<defs>',
    `<radialGradient id="door" cx="38%" cy="30%" r="75%"><stop stop-color="${gold}"/><stop offset=".45" stop-color="${bronze}"/><stop offset="1" stop-color="${background}"/></radialGradient>`,
    '</defs>',
    `<rect width="128" height="128" rx="34" fill="${background}"/>`,
    `<rect x="8" y="8" width="112" height="112" rx="28" fill="none" stroke="${gold}" stroke-width="5"/>`,
    `<circle cx="64" cy="64" r="43" fill="url(#door)" stroke="${gold}" stroke-width="4"/>`,
    `<circle cx="64" cy="64" r="31" fill="${background}" stroke="${gold}" stroke-width="3"/>`,
    `<path d="M64 33v62M33 64h62M42 42l44 44M86 42 42 86" stroke="${bronze}" stroke-width="5" stroke-linecap="round"/>`,
    `<circle cx="64" cy="64" r="13" fill="${gold}" stroke="${background}" stroke-width="5"/>`,
    `<circle cx="64" cy="64" r="4" fill="${background}"/>`,
    `<circle cx="23" cy="23" r="4" fill="${gold}"/><circle cx="105" cy="23" r="4" fill="${gold}"/>`,
    `<circle cx="23" cy="105" r="4" fill="${gold}"/><circle cx="105" cy="105" r="4" fill="${gold}"/>`,
    '</svg>',
  ].join('');
}

/** A unique address pattern inside a palette shared by the player's type. */
function renderStandard(seed, colors, name, type) {
  const [background, primary, secondary] = colors;
  const entropy = [...seed].map((char) => Number.parseInt(char, 16));
  const tiles = [];
  const size = 13;
  const gap = 3;
  const start = 25;

  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 3; col++) {
      const value = entropy[(row * 3 + col) % entropy.length] ?? 0;
      if ((value & 1) === 0) continue;
      const fill = (value & 2) === 0 ? primary : secondary;
      for (const mirrored of new Set([col, 4 - col])) {
        const x = start + mirrored * (size + gap);
        const y = start + row * (size + gap);
        tiles.push(`<rect x="${x}" y="${y}" width="${size}" height="${size}" rx="4" fill="${fill}"/>`);
      }
    }
  }

  const dash = 18 + ((entropy[31] ?? 0) * 2);
  const gapDash = 10 + (entropy[32] ?? 0);
  const initials = escapeXml(profileInitials(name));
  const title = escapeXml(`${name} — ${type}`);

  return [
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img">',
    `<title>${title}</title>`,
    '<defs>',
    `<radialGradient id="bg" cx="35%" cy="25%" r="90%"><stop stop-color="${primary}" stop-opacity=".55"/><stop offset=".55" stop-color="${background}"/><stop offset="1" stop-color="${secondary}" stop-opacity=".42"/></radialGradient>`,
    `<linearGradient id="badge" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${primary}"/><stop offset="1" stop-color="${secondary}"/></linearGradient>`,
    '</defs>',
    `<rect width="128" height="128" rx="34" fill="${background}"/>`,
    '<rect x="4" y="4" width="120" height="120" rx="31" fill="url(#bg)"/>',
    `<g opacity=".3">${tiles.join('')}</g>`,
    `<circle cx="64" cy="64" r="43" fill="none" stroke="${primary}" stroke-width="3" stroke-dasharray="${dash} ${gapDash}" opacity=".9"/>`,
    `<circle cx="64" cy="64" r="30" fill="${background}" stroke="url(#badge)" stroke-width="4"/>`,
    `<text x="64" y="73" text-anchor="middle" fill="#ffffff" font-family="ui-rounded,system-ui,sans-serif" font-size="27" font-weight="850" letter-spacing="1">${initials}</text>`,
    `<circle cx="105" cy="105" r="11" fill="${background}"/>`,
    `<circle cx="105" cy="105" r="7" fill="${primary}"/>`,
    '</svg>',
  ].join('');
}

const COLOR_RE = /^#[0-9a-fA-F]{6}$/;
const SEED_RE = /^[0-9a-f]{40}$/;
// The site-hosted mark lane: sDGNRS advertises a real logo instead of a
// generated pattern. Same allowlist the API lane uses in profiles.js.
const MARK_RE = /^\/(?:badges-circular|specials)\/[a-zA-Z0-9._/-]+$/;

/**
 * Build the avatar URL for one simulated identity.
 *
 * @param {string} key       Cache key; the profile's lowercased address.
 * @param {object} sim       {type, seed, colors, mark} from the roster file.
 * @param {string} name      Display name, drawn as initials.
 * @returns {string|null}    A data: URI, a same-origin path, or null when the
 *                           entry cannot be trusted to render.
 */
export function simAvatarUrl(key, sim, name) {
  if (cache.has(key)) return cache.get(key);
  let url = null;
  const mark = String(sim?.mark || '');
  const seed = String(sim?.seed || '').toLowerCase();
  const colors = Array.isArray(sim?.colors) ? sim.colors.map(String) : [];
  if (MARK_RE.test(mark)) {
    url = mark;
  } else if (SEED_RE.test(seed) && colors.length === 3 && colors.every((c) => COLOR_RE.test(c))) {
    const type = String(sim?.type || '');
    const svg = type === 'vault'
      ? renderVault(colors, name, type)
      : renderStandard(seed, colors, name, type);
    // encodeURIComponent, not base64: the payload is ASCII SVG, and a data:
    // URI keeps the image immutable and lifecycle-free (a blob: URL would
    // need revoking). img-src admits data:.
    url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  }
  cache.set(key, url);
  return url;
}

/** Test seam. */
export function __resetSimAvatarCache() { cache.clear(); }
